{
  "case_id": "xsu_sg_011_doctor_certificate",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret nævner ikke, at lægeattesten indhentes fra den praktiserende læge. Det fremstiller også Udbetaling Danmarks muligheder (krav om funktionel vurdering, specialisterklæringer, hospitalsjournaler m.m.) og attestens indhold (diagnose, prognose, kommunikation, deltagelse i uddannelse) på en måde, der ikke svarer til kilderne. Det hævder, at attesten skal beskrive en række ting, som kilden ikke kræver, og udelader det, kilden kræver: behov for fortsat behandling eller henvisning til specialist."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Af tre kritiske elementer er kun en generel mulighed for at indhente yderligere dokumentation delvist til stede. Praktiserende læge er ikke nævnt. Funktionsevne i forhold til den ansøgte funktionsnedsættelse er kun nævnt generelt. Behov for fortsat behandling eller henvisning til specialist mangler; svaret nævner kun 'behandling og prognose'."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret behandler begge dele af spørgsmålet: hvad Udbetaling Danmark kan gøre, og hvad en lægeattest skal beskrive. Indholdet er delvist upræcist, men det er ikke irrelevant tekst."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret angiver ingen identificerbar kilde som lov, bekendtgørelse eller vejledning."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så gyldigheden kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så det kan ikke vurderes, om kilder understøtter påstandene."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer uunderstøttede regler: at Udbetaling Danmark kan 'kræve' en funktionel vurdering, at der kan anmodes om vurderinger fra specialister, og at attesten skal indeholde diagnose, prognose, kommunikation og uddannelses- og arbejdsevne. Intet af dette findes i kildematerialet. Kilderne nævner kun lægeattest fra praktiserende læge, journaloplysninger i særlige tilfælde, en frist for yderligere dokumentation og en sagkyndig udtalelse i særlige tilfælde."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Svaret bruger 'kan' om Udbetaling Danmarks muligheder, men gengiver ikke forbeholdene i kilden: at journaloplysninger kun indhentes i særlige tilfælde, og at fremmøde som udgangspunkt kræves. Fremmødeforbeholdet kræves dog kun, hvis fremmøde omtales. Svaret skriver endvidere 'typisk' om attestens indhold, hvilket ikke afspejler kildens 'skal'-krav om funktionsevne og behandlingsbehov."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svarets trin hænger sammen internt. Manglende dokumentation giver mulighed for at indhente mere, og attestens indhold støtter vurderingen. Der er ingen indre modsigelser, selv om indholdet er forkert."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Svaret bruger 'kan kræve' om en funktionel vurdering, som kilden ikke giver hjemmel til. Attestens indhold beskrives som 'typisk', og dermed gøres kildens bindende 'skal' om funktionsevne og behandlingsbehov vagt. Samtidig gøres en række ikke-kildebårne elementer til noget, attesten 'skal' beskrive."
    }
  },
  "xhaile_coverage": {
    "A61": {
      "label": "partial",
      "reason": "Svaret siger, at Udbetaling Danmark kan indhente yderligere oplysninger og lægeattester, så muligheden for at indhente lægeattest er delvist dækket. Det nævner ikke praktiserende læge, funktionsevne i forhold til den ansøgte funktionsnedsættelse som kernen eller behovet for behandling og henvisning til specialist. Det nævner heller ikke fremmøde, særlige tilfælde for journaloplysninger eller styrelsens betaling af udgifter."
    }
  },
  "overall_notes": "Svaret er generisk og uden kildehenvisninger. Det rammer kun den overordnede mulighed for at indhente yderligere dokumentation og mangler de centrale kildebårne elementer. Samtidig tilføjer det flere uunderstøttede krav til attestens indhold og til myndighedens beføjelser."
}

